 go('pagos');$('#reminderId').value=r.id;$('#reminderName').value=r.nombre;$('#reminderAmount').value=r.monto;$('#reminderDue').value=r.fecha;$('#reminderTime').value=r.hora;$('#reminderFrequency').value=r.frecuencia;$('#reminderLead').value=String(r.anticipacion);$('#reminderSubmit').textContent='Guardar cambios';$('#reminderCancel').classList.remove('hidden');$('#reminderForm').scrollIntoView({behavior:'smooth',block:'center'});
