function reminderSave(e){e.preventDefault();const name=$('#reminderName').value.trim(),monto=Number($('#reminderAmount').value),fecha=$('#reminderDue').value,hora=$('#reminderTime').value,frecuencia=$('#reminderFrequency').value,anticipacion=Number($('#reminderLead').value);
 if(!name||!isIsoDate(fecha)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(hora)||!(monto>0)||!Number.isFinite(monto)||!['una','semanal','quincenal','mensual'].includes(frecuencia)||![0,1,2,3,7].includes(anticipacion))return alert('Revisa el nombre, monto, fecha y horario.');
 const r=state.reminders.find(r=>String(r.id)===String($('#reminderId').value));const data={nombre:name.slice(0,85),monto,fecha,hora,frecuencia,anticipacion};if(r){const changed=r.fecha!==fecha||r.frecuencia!==frecuencia;Object.assign(r,data);if(changed){r.pagados=[];removeAlertedFor(r.id)}}else state.reminders.push({id:id(),...data,pagados:[]});
 try{persist('reminders')}catch{return alert('No se pudo guardar el aviso. Descarga una copia de seguridad.')}clearReminderForm();render();toast(r?'Aviso actualizado':'Pago agendado correctamente');checkReminderAlerts();
}
function removeAlertedFor(reminderId){const history=parse(KEYS.alerted,{});Object.keys(history).filter(k=>k.startsWith(String(reminderId)+'|')).forEach(k=>delete history[k]);save(KEYS.alerted,history)}
function markReminder(reminderId,occurrence,undo=false){const r=state.reminders.find(x=>String(x.id)===String(reminderId));if(!r)return;
 if(!Array.isArray(r.pagados))r.pagados=[];if(undo){r.pagados=r.pagados.filter(d=>d!==occurrence)}else if(!r.pagados.includes(occurrence))r.pagados.push(occurrence);persist('reminders');render();toast(undo?'Pago vuelto a pendiente':'Pago marcado como realizado. No se registró un gasto adicional.');
}
async function sendOSNotification(title,body,tag){
 if(!('Notification'in window)||Notification.permission!=='granted'||!window.isSecureContext)return false;
 try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration();if(reg&&reg.showNotification){await reg.showNotification(title,{body,icon:'./icon-192.png',badge:'./icon-192.png',tag});return true}}}catch(e){}
 try{const n=new Notification(title,{body,icon:'./icon-192.png',tag});n.onclick=()=>window.focus();return true}catch(e){return false}
}
async function requestNotifs(){if(!('Notification'in window)||!window.isSecureContext){toast('Tu navegador no permite notificaciones aquí. Revisa la campana de Querux.');return}
 try{const value=await Notification.requestPermission();renderNotificationStatus();if(value==='granted')checkReminderAlerts();toast(value==='granted'?'Alertas del dispositivo activadas':value==='denied'?'Permiso denegado: usa los avisos dentro de Querux':'Permiso no concedido')}catch{toast('No fue posible activar las alertas en este navegador')}
}
async function testNotification(){if(!('Notification'in window)||Notification.permission!=='granted'){toast('Primero activa las notificaciones; la campana seguirá disponible.');return}const ok=await sendOSNotification('Querux 3.1 · Alerta de prueba','Así se mostrarán los avisos cuando Querux esté activa.','querux31-prueba');toast(ok?'Notificación de prueba enviada':'El dispositivo no mostró la alerta. Revisa permisos y la campana.')}
function checkReminderAlerts(){
 const now=new Date(),t=today(),rawHistory=parse(KEYS.alerted,{}),history=rawHistory&&typeof rawHistory==='object'&&!Array.isArray(rawHistory)?rawHistory:{};
 // Los avisos vencidos pueden aparecer al regresar, pero solo hasta 24h después del vencimiento.
 const relevant=paymentOccurrences(shiftDays(t,-1),shiftDays(t,8)).filter(o=>!o.pagado);
 relevant.forEach(o=>{
  const key=reminderKey(o),alertAt=new Date(`${shiftDays(o.fecha,-o.anticipacion)}T${o.hora||'08:00'}:00`),limit=new Date(`${shiftDays(o.fecha,1)}T00:00:00`);
  if(now<alertAt||now>=limit)return;
  const title='Querux · Recordatorio de pago',body=`${o.nombre} · ${money(o.monto)} · vence ${dateText(o.fecha)}`;
  if(!alertedSession.has(key)){alertedSession.add(key);toast(`🔔 ${o.nombre}: ${relativeDue(o)}`)}
  if(!history[key]&&'Notification'in window&&Notification.permission==='granted'){
    // Marcar antes de enviar para evitar duplicados durante cambios de pestaña.
    history[key]=new Date().toISOString();try{save(KEYS.alerted,history)}catch{}
    sendOSNotification(title,body,'querux31-'+key).then(ok=>{if(!ok){const latest=parse(KEYS.alerted,{});delete latest[key];try{save(KEYS.alerted,latest)}catch{}}});
  }
 });
}

