function exportBackup(){const o={version:3.1,exportedAt:new Date().toISOString(),movimientos:state.mov,presupuestos:state.bud,metaAhorro:state.goal,metaFecha:state.goalDate,catBudgets:state.catBud,recurrentes:state.rec,cuentas:state.acc,transferencias:state.trans,deudas:state.debts,avisosProgramados:state.reminders,categoriasPersonalizadas:state.cats,nombreUsuario:profileName(),tema:localStorage.getItem(KEYS.theme)||'dark'};download('querux31-respaldo-'+today()+'.json',JSON.stringify(o,null,2),'application/json;charset=utf-8');toast('Copia de seguridad descargada')}
function exportCSV(){const q=v=>{const s=String(v??'');return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s};const rows=[['Fecha','Tipo','Categoría','Detalle','Monto','Cuenta'],...sorted(state.mov).reverse().map(m=>[m.fecha,typeOf(m),m.categoria,m.detalle||'',N(m.monto).toFixed(2),acct(m.cuenta||m.accountId||'principal')?.nombre||'Principal'])];download('querux3-movimientos-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV exportado')}
async function restore(file){try{if(!file)return;if(file.size>20*1024*1024)throw Error('Archivo demasiado grande.');const data=JSON.parse(await file.text());if(!data||typeof data!=='object'||!Array.isArray(data.movimientos)||data.movimientos.some(m=>!m||typeof m!=='object'||!['ingreso','gasto','ahorro'].includes(m.tipo)||!Number.isFinite(Number(m.monto))||N(m.monto)<0))throw Error('Copia incompatible: movimientos inválidos.');if(data.cuentas!==undefined&&!Array.isArray(data.cuentas))throw Error('El formato de las cuentas no es válido.');confirmBox('Restaurar copia','Esta acción reemplazará TODOS los registros actuales. Antes se descargará automáticamente una copia de tus datos. ¿Deseas continuar?',()=>{const before={...state,mov:[...state.mov],acc:[...state.acc]};const keys=Object.values(KEYS),saved={};keys.forEach(k=>saved[k]=localStorage.getItem(k));try{exportBackup();state.mov=data.movimientos;state.bud=data.presupuestos&&typeof data.presupuestos==='object'&&!Array.isArray(data.presupuestos)?data.presupuestos:{};state.goal=N(data.metaAhorro);state.goalDate=String(data.metaFecha||'');state.catBud=data.catBudgets&&typeof data.catBudgets==='object'&&!Array.isArray(data.catBudgets)?data.catBudgets:{};state.rec=Array.isArray(data.recurrentes)?data.recurrentes:[];state.acc=Array.isArray(data.cuentas)?data.cuentas:basicAccounts();state.trans=Array.isArray(data.transferencias)?data.transferencias:[];state.debts=Array.isArray(data.deudas)?data.deudas:[];state.reminders=Array.isArray(data.avisosProgramados)?data.avisosProgramados.filter(r=>r&&/^\d{4}-\d{2}-\d{2}$/.test(r.fecha||'')).map(r=>({...r,pagados:Array.isArray(r.pagados)?r.pagados:[]})):[];state.cats=data.categoriasPersonalizadas||{gasto:[],ingreso:[]};if(!Array.isArray(state.cats.gasto)||!Array.isArray(state.cats.ingreso))state.cats={gasto:[],ingreso:[]};if(!state.acc.some(a=>a.id==='principal'))state.acc.unshift(basicAccounts()[0]);if(!state.acc.some(a=>a.id==='ahorros'))state.acc.push(basicAccounts()[1]);persist('mov','bud','goal','catBud','rec','acc','trans','debts','cats','reminders');localStorage.removeItem(KEYS.alerted);if(data.tema)setTheme(data.tema);if(typeof data.nombreUsuario==='string'){const nombre=data.nombreUsuario.replace(/\s+/g,' ').trim().slice(0,40);if(nombre){localStorage.setItem(KEYS.profile,nombre);localStorage.setItem(KEYS.profileSeen,'1')}else localStorage.removeItem(KEYS.profile)}$('#txMonth').value='';$('#budgetMonth').value=month();render();toast('Copia restaurada correctamente')}catch(e){Object.entries(saved).forEach(([k,v])=>{try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch{}});Object.assign(state,before);render();alert('No se pudo restaurar. Los datos anteriores siguen guardados. '+e.message)}})}catch(err){alert('No se puede restaurar el archivo. '+err.message)}finally{$('#backupFile').value=''}}
function txSave(e){e.preventDefault();const monto=N($('#txAmount').value),tipo=$('#txType').value,fecha=$('#txDate').value;const accountId=$('#txAccount').value;if(monto<=0||!Number.isFinite(monto)||!/\d{4}-\d{2}-\d{2}/.test(fecha))return alert('Verifica monto y fecha.');if(tipo==='ahorro'&&accountId==='ahorros')return alert('Selecciona una cuenta distinta de Ahorros para apartar dinero.');let m=state.mov.find(m=>String(m.id)===String($('#txId').value));const edited=Boolean(m);if(!m){m={id:id()};state.mov.push(m)}m.tipo=tipo==='ahorro'?'gasto':tipo;m.categoria=tipo==='ahorro'?'Ahorro':$('#txCategory').value;m.monto=monto;m.fecha=fecha;m.detalle=$('#txDetail').value.trim();m.cuenta=accountId;if(tipo!=='gasto'||!m.recurrenteId)delete m.recurrenteId;if(m.deudaId&&(tipo!=='gasto'||m.categoria!=='Préstamo'))delete m.deudaId;syncDebts();try{persist('mov','debts')}catch{return alert('No se pudo guardar en el navegador. Descarga una copia e intenta liberar espacio.')}clearTxForm();render();toast(edited?'Movimiento actualizado':'Movimiento guardado correctamente');if(!edited)showMascot(tipo,monto)}
function clearTxForm(){$('#txForm').reset();$('#txId').value='';$('#txFormTitle').textContent='Nuevo movimiento';$('#txSave').textContent='Guardar movimiento';$('#txCancel').classList.add('hidden');$('#txDate').value=today();$('#txType').value='gasto';fillCategories()}
function editTx(x){const m=state.mov.find(m=>String(m.id)===String(x));if(!m)return;go('movimientos');$('#txId').value=m.id;$('#txType').value=typeOf(m);fillCategories();const c=$('#txCategory');if(![...c.options].some(o=>o.value===m.categoria))c.add(new Option(m.categoria,m.categoria));c.value=m.categoria;$('#txAmount').value=m.monto;$('#txDate').value=m.fecha;$('#txAccount').value=m.cuenta||m.accountId||'principal';$('#txDetail').value=m.detalle||'';$('#txFormTitle').textContent='Editar movimiento';$('#txSave').textContent='Guardar cambios';$('#txCancel').classList.remove('hidden');$('#txForm').scrollIntoView({behavior:'smooth',block:'center'})}
function showMascot(type,amount){const box=$('#mascotPopup');if(!box)return;const img=$('#mascotPopupImage'),ok=type==='ingreso'||type==='ahorro';img.src=ok?'mascota-ingreso.jpg':'mascota-gasto.jpg';img.dataset.fallback='';img.dataset.remote=ok?'mascota-ingreso.jpg':'mascota-gasto.jpg';$('#mascotPopupAmount').textContent=(type==='ingreso'?'+ ':type==='ahorro'?'◈ ':'− ')+money(amount);$('#mascotPopupTitle').textContent=type==='ingreso'?'¡Ingreso registrado!':type==='ahorro'?'¡Ahorro registrado!':'¡Gasto registrado!';box.classList.add('show');clearTimeout(window.__mascotTimer);window.__mascotTimer=setTimeout(()=>box.classList.remove('show'),1350)}
